function selectionner_tout()
{

if(option==0)
    {
for (i = 0; i < document.getElementsByName('list').length; i++)
	document.getElementsByName('list')[i].checked = true ;
option=1;
	}	
else
   {
for (i = 0; i < document.getElementsByName('list').length; i++)
	document.getElementsByName('list')[i].checked = false ;
	option=0;
   }	
}
